mapper.select:
SELECT FROM products WHERE NOT deleted
AND category = #{category}
AND (created_at, id) < (#{afterTime}, CAST(#{afterId} AS uuid))
ORDER BY created_at DESC, id DESC LIMIT #{limit}

SELECT p.id, p.name, p.category, c.display_name, p.price_minor, p.status
FROM products p LEFT JOIN product_categories c ON p.category = c.code
WHERE NOT p.deleted AND p.category = #{category}
    AND p.status = #{status} AND p.price_minor >= #{minPrice}
ORDER BY p.created_at DESC, p.id DESC
LIMIT #{limit}
